INSERT INTO public.movies (id, title, original_title, overview, release_date, poster_path, backdrop_path, vote_average, vote_count, popularity, runtime, tagline, trailer_url) VALUES
(804680, 'Mirzapur: The Movie', 'Mirzapur: The Movie', 'The colossal theatrical cinematic universe debut of Mirzapur. Kaleen Bhaiya, Guddu Pandit, and Munna Bhaiya collide on the big screen in a ruthless, all-out war for total supremacy over the Purvanchal throne.', '2026-09-01', 'https://i.ytimg.com/vi/5vMWZhHPlaw/maxresdefault.jpg', 'https://img.etimg.com/thumb/msid-134229973,width-650,height-488,imgsize-118767,resizemode-75/mirzapur-the-movie.jpg', 8.8, 19500, 250.0, 165, 'Bhowkaal will now explode on the Big Screen.', 'https://www.youtube.com/watch?v=5vMWZhHPlaw'),
(1498287, 'Freddy', 'Freddy', 'In a second-rate variety company, a strange Hungarian fortune teller, a magician with a criminal record, a ventriloquist who uses a dummy named Freddy, a singer, and a group of girls who can no longer find work in top-tier theaters all live together.', '1982-01-01', '/5MzIz4fJPNjgvE8xyJljLzMIizK.jpg', '/5MzIz4fJPNjgvE8xyJljLzMIizK.jpg', 10.0, 12500, 240.0, 145, 'Experience the brilliance of Freddy.', 'https://www.youtube.com/watch?v=pXQ0lH8BPNA'),
(877189, 'The Glass Breakfront', 'The Glass Breakfront', 'A man enters a museum of antiquities late at night to escape a monster lurking in the darkness.', '2021-01-01', '/sJM0qzjdaepTn8x7inKYtV7P4r0.jpg', '/sJM0qzjdaepTn8x7inKYtV7P4r0.jpg', 10.0, 12500, 240.0, 145, 'Experience the brilliance of The Glass Breakfront.', 'https://www.youtube.com/watch?v=huHmSP48oc0'),
(101088, 'Panchayat', 'Panchayat', 'Abhishek Tripathi, an engineering graduate, navigates the quirky challenges and eccentric politics of rural India as the secretary of a Gram Panchayat in the quiet village of Phulera.', '2020-04-03', 'https://m.media-amazon.com/images/S/pv-target-images/b11c79ea017bf6ce6a6d1690c6c264128f2612c2d4effd89bc47a224c5521a78.jpg', '/hZi6c59gGDQuFy2LBkru74Cmygo.jpg', 8.9, 22000, 240.0, 45, 'Lauki, Chai, aur Phulera ki Siyasat.', 'https://www.youtube.com/watch?v=mojZJ7oeD_g'),
(991201, 'Dhurandhar', 'Dhurandhar', 'An elite Indian intelligence officer orchestrates a high-stakes undercover global counter-terror operation against a ruthless syndicate spanning cross-border networks.', '2025-10-02', 'https://upload.wikimedia.org/wikipedia/en/c/ce/Dhurandhar_poster.jpg', 'https://i.ytimg.com/vi/NHk7scrb_9I/maxresdefault.jpg', 8.4, 12800, 235.0, 165, 'The ultimate covert tactical strike.', 'https://www.youtube.com/watch?v=NHk7scrb_9I'),
(485327, 'Bhagam Bhag', 'Bhagam Bhag', 'Two jobless men become entangled in a series of chases and conflicts when they try to hang on to an extremely valuable coat that a fleeing criminal dropped in their apartment.', '1956-01-01', '/8C6heiUMZ5Nu2nej9HnqzmH0u77.jpg', '/8C6heiUMZ5Nu2nej9HnqzmH0u77.jpg', 9.0, 12500, 230.0, 145, 'Experience the brilliance of Bhagam Bhag.', 'https://www.youtube.com/watch?v=gr6aJozC-dw'),
(19404, 'Dilwale Dulhania Le Jayenge', 'Dilwale Dulhania Le Jayenge', 'Raj is a rich, carefree, happy-go-lucky second generation NRI. Simran is the daughter of Chaudhary Baldev Singh, who in spite of being an NRI is very strict about adherence to Indian values. Simran has left for India to be married to her childhood fiancé. Raj leaves for India with a mission at his hands, to claim his lady love under the noses of her whole family. Thus begins a saga.', '1995-01-01', '/lfRkUr7DYdHldAqi3PwdQGBRBPM.jpg', '/84beTJf26mfhoasUlKSOiNSutyS.jpg', 8.5, 12500, 225.0, 145, 'Experience the brilliance of Dilwale Dulhania Le Jayenge.', 'https://www.youtube.com/watch?v=oIZ4U21DRlM'),
(138211, 'Rocket Boys', 'Rocket Boys', 'Spanning three crucial decades (1940-60s) in the history of India, the story chronicles the life of three great men responsible for launching India''s space and nuclear programs respectively: Dr. Homi J. Bhabha, the architect of India''s Nuclear Programme, Dr. Vikram Sarabhai, universally acknowledged as the Father of the Indian Space Programme and Dr. A.P.J. Abdul Kalam, the pioneer of modern Indian aerospace and nuclear technology. The season traces the journey of Bhabha and Sarabhai coming to terms with the challenges facing a young, independent nation and their friendship, sacrifice and determination.', '2022-01-01', '/esNv5JwxVsvu6vZE7bTVeu0mLaA.jpg', '/kOGM01ZhELmJCxdVObqQbRwXXH3.jpg', 8.4, 12500, 224.0, 45, 'Experience the brilliance of Rocket Boys.', 'https://www.youtube.com/watch?v=rOD-78_0pPU'),
(243206, 'Pritam and Pedro', 'Pritam and Pedro', 'The dynamic between the two contrasting personalities, a seasoned cop who prefers old-school methods and a tech-savvy cop who relies on modern technology for investigations, as they navigate their partnership in solving crimes.', '2026-01-01', '/uA5hAexR9Xis3BzSOMKjNuYQUsj.jpg', '/eAXSlqAJwpdsZ59G10lao9OJ4SG.jpg', 8.4, 12500, 224.0, 45, 'Experience the brilliance of Pritam and Pedro.', 'https://www.youtube.com/watch?v=JU_9IrpJyMo'),
(299536, 'Avengers: Infinity War', 'Avengers: Infinity War', 'As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment - the fate of Earth and existence itself has never been more uncertain.', '2018-01-01', '/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', '/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', 8.2, 12500, 222.0, 145, 'Experience the brilliance of Avengers: Infinity War.', 'https://www.youtube.com/watch?v=QwievZ1Tx-8'),
(100612, 'Special Ops', 'Special Ops', 'The series follows Himmat Singh of Research and Analysis Wing who draws similar patterns in terrorist attacks and is convinced a single person is behind all the attacks. His task force team of five agents living in various parts of the world aim to catch the mastermind. The story is based on an inspiration taken from nineteen years worth of national significant events.', '2020-01-01', '/rTOGcNzVMYGezpx9AxX7ilzLNEp.jpg', '/A7A1s8O4M2rFlAbbcSlIxrgCY9i.jpg', 8.2, 12500, 222.0, 45, 'Experience the brilliance of Special Ops.', 'https://www.youtube.com/watch?v=iaNXfCYW91U'),
(138396, 'Special Ops 1.5 The Himmat Story', 'Special Ops 1.5 The Himmat Story', 'After the 2001 Parliament attack, a young and idealistic RA&W officer had a theory. In 2003, he had a mystery. This is the story of Himmat Singh', '2021-01-01', '/nH5LDmNofN4p5mldUxxhVzfn4sk.jpg', '/uRYNOAfaGqDMhHxbMJ6i3zwNE91.jpg', 8.2, 12500, 222.0, 45, 'Experience the brilliance of Special Ops 1.5 The Himmat Story.', 'https://www.youtube.com/watch?v=1ZTShnS3Uss'),
(213895, 'The Railway Men - The Untold Story of Bhopal 1984', 'The Railway Men - The Untold Story of Bhopal 1984', 'India, 1984. After a deadly gas leaks from a factory in Bhopal, brave railway workers risk their lives to save others in the face of an unspeakable disaster.', '2023-01-01', '/kOYlMHtNSqnf1FgsoK1JJypfkrY.jpg', '/s7dpEDsAan8mvC5cikvWidOupsO.jpg', 8.1, 12500, 221.0, 45, 'Experience the brilliance of The Railway Men - The Untold Story of Bhopal 1984.', 'https://www.youtube.com/watch?v=htQsI-b9dgc'),
(89113, 'Kota Factory', 'Kota Factory', 'In a city of coaching centers known to train India’s finest collegiate minds, an earnest but unexceptional student and his friends navigate campus life.', '2019-01-01', '/fMBookmwL6HjIgIVTjQ6EMr3pCH.jpg', '/mQEmKXSFlzBlSoYgut0VfjxAzoA.jpg', 8.1, 12500, 221.0, 45, 'Experience the brilliance of Kota Factory.', 'https://www.youtube.com/watch?v=pNZQ6msbOvM'),
(96312, 'Cubicles', 'Cubicles', 'This world is actually run by people sitting and working in their cubicles. This is a story of Piyush Prajapati, a 22 year old, fresh out of college and recruited like most of his batch-mates into an Indian IT company. From the time he gets his first salary, working weekends, work-life balance, a little bit of heart to all kinds of highs and lows, the show follows many firsts and chronicles the life of Piyush, a typical Indian first jobber and the people around him.', '2019-01-01', '/vfjIBMXJK8rmvJ3SrAInlhM7v5e.jpg', '/pZsdCRo0gXJoR0EGpRNzzZjiPxj.jpg', 8.1, 12500, 221.0, 45, 'Experience the brilliance of Cubicles.', 'https://www.youtube.com/watch?v=1Ywmv5yVUr8'),
(229403, 'Scam 2003: The Telgi Story', 'Scam 2003: The Telgi Story', 'It will follow the life of Telgi, born in Khanapur in the state of Karnataka, as he became the mastermind behind one of India’s most ingenious scams, which spread across 18 states and shook the entire country', '2023-01-01', '/wsTVqPNNOOvUXKRJv0DstHUDIw8.jpg', '/cpt1ag1Oy4yOch8qd4TUPHIwCsX.jpg', 8.1, 12500, 221.0, 45, 'Experience the brilliance of Scam 2003: The Telgi Story.', 'https://www.youtube.com/watch?v=JrotIxxCXiA'),
(928172, 'Pritam and Pedro', 'Pritam and Pedro', 'A brilliant, sharp-witted young hacker Pritam and an unorthodox, seasoned cop Pedro find themselves forced into an eccentric partnership to crack high-stakes digital heists and dismantle a massive cyber-crime network.', '2026-07-03', 'https://i.ytimg.com/vi/uCjkRVV0-qU/maxresdefault.jpg', '/oc6b6LxsKAfqryozD8lUJcimPDL.jpg', 8.5, 14200, 220.0, 48, 'Genius Hacker meets Noob Cop.', 'https://www.youtube.com/watch?v=uCjkRVV0-qU'),
(1029827, 'Drishyam 2', 'Drishyam 2', '7 years after the case related to Vijay Salgaonkar and his family was closed, a series of unexpected events bring truth to light that threatens to change everything for the Salgaonkars. Can Vijay save his family this time?', '2022-01-01', '/wk8Vu0DI0MiNLaXXiVqAwjLRKL5.jpg', '/498aYGlnvjvoiqXYhCNHrZERi4l.jpg', 8.0, 12500, 220.0, 145, 'Experience the brilliance of Drishyam 2.', 'https://www.youtube.com/watch?v=cxA2y9Tgl7o'),
(386449, 'Ittefaq', 'Ittefaq', 'Shiva is a professional hit man. Shiva accepts a contract from Jindal to kill Vikram. Circumstances force Shiva to come to know Mukul first, and instead of killing him, he becomes his bodyguard and protects him against Jindal and his men. Soon Shiva, Mukul, and Mukul''s girlfriend Roshni Hiranandani are on the run from Jindal''s men. Jindal makes it clear that he will not rest until he sees the dead bodies of all the three. How long will they survive Jindal? Did Shiva really change his mind or is this his strategy to bring Mukul alive to Jindal?', '2001-01-01', '/qAYS6v142dUnw27G5cUQRBCyWo7.jpg', '/sKBCJneTUqNku7mxgOaw5EUzTJY.jpg', 8.0, 12500, 220.0, 145, 'Experience the brilliance of Ittefaq.', 'https://www.youtube.com/watch?v=mvfvoCdPrII'),
(535144, 'Sonchiriya', 'Sonchiriya', 'A legion of warring bandits terrorizes India''s Chambal Valley.', '2019-01-01', '/7ygikeDbneOlUFIQyvAmMrvi3vJ.jpg', '/fVxbEDd7ci0TE4ljsK13oyNUeW7.jpg', 8.0, 12500, 220.0, 145, 'Experience the brilliance of Sonchiriya.', 'https://www.youtube.com/watch?v=aejAkKGiimk'),
(412961, 'Mr. X in Bombay', 'Mr. X in Bombay', 'Shobha Mathur lives a wealthy lifestyle with her Professor dad, who is now carrying out experiments on various issues. One day while doing so, he makes an employee named Manohar drink a potion, which results in his death. Rajan comes to their rescue, gets rid of the body, and starts blackmailing Mathur, which can only end when Shobha marries Rajan. Then one day Shobha meets a poet by the name of Sudarshan and both of them fall in love. When he asks for her hand in marriage, Shobha refuses. The next day Shobha finds a note addressed to her from Sudarshan in which he has stated that he is going to kill himself. Thereafter, every night she starts to hear Sudarshan''s voice, blaming her for his death, as his soul is unable to find solace. With Sudarshan out of the way, Rajan readies himself for marrying Shobha - and it looks like he may have his way with the Mathurs after all - without having to encounter any more obstacles.', '1964-01-01', '/uNbwjNnFCuudtTHZBfvCu2DxiGk.jpg', '/7hYFQPlE4GXRLJDNQJDLbpDkAF8.jpg', 8.0, 12500, 220.0, 145, 'Experience the brilliance of Mr. X in Bombay.', 'https://www.youtube.com/watch?v=1bRSXb5Lucc'),
(7508, 'Like Stars on Earth', 'Like Stars on Earth', 'Ishaan Awasthi is an eight-year-old whose world is filled with wonders that no one else seems to appreciate. Colours, fish, dogs, and kites don''t seem important to the adults, who are much more interested in things like homework, marks, and neatness. Ishaan cannot seem to get anything right in class; he is then sent to boarding school, where his life changes forever.', '2007-01-01', '/puHRt6Raovm5ujGCdwLWvRv4NHU.jpg', '/bPwdy3zaNnMdZ22u0WCcYu0xxgt.jpg', 8.0, 12500, 220.0, 145, 'Experience the brilliance of Like Stars on Earth.', 'https://www.youtube.com/watch?v=tn_2Ie_jtX8'),
(20453, '3 Idiots', '3 Idiots', 'Rascal. Joker. Dreamer. Genius... You''ve never met a college student quite like "Rancho." From the moment he arrives at India''s most prestigious university, Rancho''s outlandish schemes turn the campus upside down—along with the lives of his two newfound best friends. Together, they make life miserable for "Virus," the school’s uptight and heartless dean. But when Rancho catches the eye of the dean''s daughter, Virus sets his sights on flunking out the "3 idiots" once and for all.', '2009-01-01', '/66A9MqXOyVFCssoloscw79z8Tew.jpg', '/8gT3UKtglLVpu0YfccwbmXZ5Eis.jpg', 8.0, 12500, 220.0, 145, 'Experience the brilliance of 3 Idiots.', 'https://www.youtube.com/watch?v=zIKu9k50SDo'),
(26022, 'My Name Is Khan', 'My Name Is Khan', 'Rizwan Khan, a Muslim from the Borivali section of Mumbai, has Asperger''s syndrome. He marries a Hindu single mother, Mandira, in San Francisco. After 9/11, Rizwan is detained by authorities at LAX who treat him as a terrorist because of his condition and his race.', '2010-01-01', '/5Y36lCiNyyV71mjq6LavgiggbhT.jpg', '/zGCnIADWwpjGllYv8DgT8HIuIQl.jpg', 8.0, 12500, 220.0, 145, 'Experience the brilliance of My Name Is Khan.', 'https://www.youtube.com/watch?v=nqxgYT3TYzY'),
(84105, 'Mirzapur', 'Mirzapur', 'The iron-fisted Akhandanand Tripathi is a millionaire carpet exporter and the mafia don of Mirzapur. His son, Munna, is an unworthy, power-hungry heir who will stop at nothing to inherit his father''s legacy. An incident at a wedding procession forces him to cross paths with Ramakant Pandit, an upstanding lawyer, and his sons, Guddu and Bablu. It snowballs into a game of ambition, power and greed that threatens the fabric of this lawless city.', '2018-01-01', '/1rxLUFVrtTo82OxhbDXJDiJVkwL.jpg', '/3dV7pWAdwIPKR2lMIACMfObXdgK.jpg', 8.0, 12500, 220.0, 45, 'Experience the brilliance of Mirzapur.', 'https://www.youtube.com/watch?v=33o3s4Vs4Sw'),
(308789, 'Asur: Welcome to Your Dark Side', 'Asur: Welcome to Your Dark Side', 'Set against the backdrop of the mystical city of Varanasi, Asur follows Nikhil Nair, a forensic-expert-turned-teacher, who returns to his roots at the Central Bureau of Investigation, and along with his former mentor Dhananjay Rajpoot, finds himself caught in a cat and mouse game with a brutal serial killer.', '2020-01-01', '/aeMnaSgGAafd6y2fAzkMszRBscA.jpg', '/8z8uPdpCBxGMQQGr8IfxRSbXNFs.jpg', 8.0, 12500, 220.0, 45, 'Experience the brilliance of Asur: Welcome to Your Dark Side.', 'https://www.youtube.com/watch?v=oveko3h4pxk'),
(105759, 'Undekhi', 'Undekhi', 'Show depicts the two aspects of the society - the power-drunk influential people who think they can get away with anything and the oppressed, subjected to years of torture, who finally decide to bring themselves to justice', '2020-01-01', '/mzm5gUiv1oRkpLy7f3aFkDIFbbP.jpg', '/8Oe8yZqR20AThApCxWvTsRwIa9d.jpg', 8.0, 12500, 220.0, 45, 'Experience the brilliance of Undekhi.', 'https://www.youtube.com/watch?v=hyJQPjbsIs8'),
(1163258, '12th Fail', '12th Fail', 'Based on the true story of IPS officer Manoj Kumar Sharma, 12th Fail sheds limelight on fearlessly embracing the idea of restarting the academic journey despite the setbacks and challenges and reclaiming one''s destiny at a place where millions of students attempt the world''s toughest competitive exam: UPSC.', '2023-01-01', '/eebUPRI4Z5e1Z7Hev4JZAwMIFkX.jpg', '/6RV2o8PBCEyw9ylOWViV1CtULIF.jpg', 7.9, 12500, 219.0, 145, 'Experience the brilliance of 12th Fail.', 'https://www.youtube.com/watch?v=KjbtuqENvVE'),
(381418, 'Sanam Teri Kasam', 'Sanam Teri Kasam', 'Tough ex-convict Inder and traditional mousy Saraswati fall in love and get married, but a tragedy changes their lives forever. The film is a modern rendition of the legends of Shiva-Sati and the novel "Love Story" by Eric Segal.', '2016-01-01', '/xb9T5kMSq4pp9CDUgO5oQAy6p4q.jpg', '/4qifcARBYMzaKgIeaPNTYXLikXd.jpg', 7.9, 12500, 219.0, 145, 'Experience the brilliance of Sanam Teri Kasam.', 'https://www.youtube.com/watch?v=XXQaKHlyC1o'),
(81166, 'Yeh Meri Family', 'Yeh Meri Family', 'Set in the summer of 1998 it is a story about conflicting emotions towards family members from the eyes of a twelve year old.', '2018-01-01', '/7F33yqUYIzmFQwDibEjPoJxxTXg.jpg', '/iKIfIOPdD0pZsR2KbvTpv4kgsnT.jpg', 7.9, 12500, 219.0, 45, 'Experience the brilliance of Yeh Meri Family.', 'https://www.youtube.com/watch?v=27CqzEKvK9I'),
(126400, 'Gangs of Wasseypur - Part 2', 'Gangs of Wasseypur - Part 2', 'After the death of his father and brother Danish, Faizal Khan vows to take revenge by destroying Ramadhir Singh''s gang.', '2012-01-01', '/4CVPyT10Cvw9BCgWNKXiRcXntuc.jpg', '/nXkNbKFx8YLorku25MMLO5OV6aW.jpg', 7.8, 12500, 218.0, 145, 'Experience the brilliance of Gangs of Wasseypur - Part 2.', 'https://www.youtube.com/watch?v=XuK5TAEIqfg'),
(79352, 'Sacred Games', 'Sacred Games', 'A link in their pasts leads an honest cop to a fugitive gang boss, whose cryptic warning spurs the officer on a quest to save Mumbai from cataclysm.', '2018-01-01', '/uEbNtFbK4At9WBDGap23lt1qO9n.jpg', '/qtac9X9lSLqZFbxS71347N8MiID.jpg', 7.8, 12500, 218.0, 45, 'Experience the brilliance of Sacred Games.', 'https://www.youtube.com/watch?v=w-Xe8gLBc5I'),
(132117, 'Farzi', 'Farzi', 'Sunny, a brilliant small-time artist is catapulted into the high-stakes world of counterfeiting when he creates the perfect fake currency note, even as Michael, a fiery, unorthodox task force officer wants to rid the country of the counterfeiting menace. In this thrilling cat-and-mouse race, losing is not an option!', '2023-01-01', '/cTS86RwEBIDgCgUmjWQTSoPsK6p.jpg', '/rGkjtv6UdL1ysDmZuBjbNl3PAA1.jpg', 7.8, 12500, 218.0, 45, 'Experience the brilliance of Farzi.', 'https://www.youtube.com/watch?v=KQdgKpNYho8'),
(87508, 'Delhi Crime', 'Delhi Crime', 'Following the police force as they investigate high-profile crimes in Delhi, this series has seasons inspired by both real and fictional events.', '2019-01-01', '/xkpkTj6KGsjSaet0VQaq0aTn31D.jpg', '/j6djmR4hi8ULL0xUPQN4ZVyzgVN.jpg', 7.8, 12500, 218.0, 45, 'Experience the brilliance of Delhi Crime.', 'https://www.youtube.com/watch?v=jNuKwlKJx2E'),
(213635, 'Khakee: The Bihar Chapter', 'Khakee: The Bihar Chapter', 'As a righteous cop pursues a merciless criminal in Bihar, he finds himself navigating a deadly chase and a moral battle mired in corruption.', '2022-01-01', '/xvr3WrwAQMlcb00OZEos9nLekTE.jpg', '/avF57irLYDIn5rYhgLCnM0QlVmJ.jpg', 7.8, 12500, 218.0, 45, 'Experience the brilliance of Khakee: The Bihar Chapter.', 'https://www.youtube.com/watch?v=XneHBxjMg_Y'),
(90966, 'Gullak', 'Gullak', 'Set in quaint by-lanes in the heart of India, Gullak is a collection of disarming and relatable tales of the Mishra family.', '2019-01-01', '/arn3mvRYSrEqO7vaKbH8QxM8EEK.jpg', '/t0J74zw5N5Ux7CvvBtIHvjnSB4n.jpg', 7.8, 12500, 218.0, 45, 'Experience the brilliance of Gullak.', 'https://www.youtube.com/watch?v=XKVYXYuPUm8'),
(217699, 'Trial by Fire', 'Trial by Fire', 'After the deadly Uphaar cinema fire, two grief-stricken parents navigate the loss of their kids and a dogged fight for justice.', '2023-01-01', '/rhxP4qaHvheSzM5iVIxSg9D6nU4.jpg', '/p2vOVks5CpzywWjEecF3u88QCoI.jpg', 7.8, 12500, 218.0, 45, 'Experience the brilliance of Trial by Fire.', 'https://www.youtube.com/watch?v=7rMFBiglRXI'),
(10757, 'Kabhi Khushi Kabhie Gham', 'Kabhi Khushi Kabhie Gham', 'Years after his father disowns his adopted brother for marrying a woman of lower social standing, a young man goes on a mission to reunite his family.', '2001-01-01', '/eJrD94E1msYEa0DygvkvdEKpChm.jpg', '/sPMBiyjTco4JdKojlfGIz5Wd0jC.jpg', 7.7, 12500, 217.0, 145, 'Experience the brilliance of Kabhi Khushi Kabhie Gham.', 'https://www.youtube.com/watch?v=7uY1JbWZKPA'),
(61859, 'The Night Manager', 'The Night Manager', 'Former British soldier Jonathan Pine navigates the shadowy recesses of Whitehall and Washington where an unholy alliance operates between the intelligence community and the secret arms trade. To infiltrate the inner circle of lethal arms dealer Richard Onslow Roper, Pine must himself become a criminal.', '2016-01-01', '/1MccRnw41qQjREuZkovqP2UX1i3.jpg', '/2vAOdruqvx9GojXxKi3xVsZZvKU.jpg', 7.7, 12500, 217.0, 45, 'Experience the brilliance of The Night Manager.', 'https://www.youtube.com/watch?v=g-ZcaKdvML8'),
(124411, 'Aspirants', 'Aspirants', 'Aspirants is a story of 3 friends - Abhilash, SK, and Guri. The story takes place in the past and the present where the past captures the struggle and the drama behind the making of UPSC CSE aspirants in Old Rajinder Nagar of Delhi, while the present talks about the aftermath. It is the story of three UPSC aspirants journey.', '2021-01-01', '/lG8wK40jH4EX6dbVFI1fzw2E96N.jpg', '/1g3856hsrYrSp6gWQMUpwqDw8Nb.jpg', 7.7, 12500, 217.0, 45, 'Experience the brilliance of Aspirants.', 'https://www.youtube.com/watch?v=jWUQ2A-LxNo'),
(63180, 'TVF Pitchers', 'TVF Pitchers', 'A story of trials and tribulations of four young entrepreneurs who quit their day jobs in order to pursue their start up venture.', '2015-01-01', '/w0A288hXCytNIi9Kh7VkKE8MQ1W.jpg', '/AkhbsjGma7KnwN8Z63yqGMrunv6.jpg', 7.7, 12500, 217.0, 45, 'Experience the brilliance of TVF Pitchers.', 'https://www.youtube.com/watch?v=84Jk1OqDqOo'),
(534780, 'Andhadhun', 'Andhadhun', 'A series of mysterious events changes the life of a blind pianist who now must report a crime that was actually never witnessed by him.', '2018-01-01', '/dy3K6hNvwE05siGgiLJcEiwgpdO.jpg', '/ArvKQJv3nEpnBoVyjWDUT7TtJOL.jpg', 7.6, 12500, 216.0, 145, 'Experience the brilliance of Andhadhun.', 'https://www.youtube.com/watch?v=2iVYI99VGaw'),
